rooms = {
    "hall":    {"text": "A dusty hall. Doors lead north and east.",
                "exits": {"north": "library", "east": "kitchen"}, "item": None},
    "library": {"text": "Shelves of old books. A door leads south.",
                "exits": {"south": "hall"}, "item": "lamp"},
    "kitchen": {"text": "A cold kitchen. Doors lead west and north.",
                "exits": {"west": "hall", "north": "vault"}, "item": "key"},
    "vault":   {"text": "Gold glitters in the lamplight. You found the treasure!",
                "exits": {}, "item": None, "locked": True},
}

def play():
    room, inventory = "hall", []
    print(rooms[room]["text"])
    while True:
        command = input("> ").strip().lower().split()
        if not command:
            continue
        verb, noun = command[0], (command[1] if len(command) > 1 else "")

        if verb == "go":
            target = rooms[room]["exits"].get(noun)
            if target is None:
                print("You cannot go that way.")
            elif rooms[target].get("locked") and "key" not in inventory:
                print("The door is locked. You need a key.")
            elif target == "vault" and "lamp" not in inventory:
                print("It is pitch dark in there. You need a lamp.")
            else:
                room = target
                print(rooms[room]["text"])
                if room == "vault":
                    print("You win!")
                    return
        elif verb == "take":
            if rooms[room]["item"] == noun:
                inventory.append(noun)
                rooms[room]["item"] = None
                print(f"You take the {noun}.")
            else:
                print("There is nothing like that here.")
        elif verb == "look":
            item = rooms[room]["item"]
            print(rooms[room]["text"] + (f" You see a {item}." if item else ""))
        elif verb == "inventory":
            print("You carry:", ", ".join(inventory) or "nothing")
        elif verb == "quit":
            print("Goodbye.")
            return
        else:
            print("Try: go <direction>, take <item>, look, inventory, quit")

play()
